    """Key rule property of ApplintEORule.

    Parameters:
        key (str): uppercase string or dict.

    Returns:
        bool: True if any key is missing or mismatch.
    """
    ret = True
    keys = pyScript.common_layout.key_rule_list
    for k in keys:
        if k not in key:
            return False
    if isinstance(key, dict):
        for k in pyScript.common_layout.key_rule_dict:
            if key.get(k) != keys[k]:
